"""Generated byte arrays exercise guest CRT operations without executable input."""
import pytest
from test_winapi_model import fixture_model
from unpacker.winapi_model import UnsupportedAPI


def test_guest_string_copy_compare_padding_and_counted_truncation():
    model, uc, _ = fixture_model()
    api = model.crt_buffers
    uc.mem_write(0x100, b'benign\0')
    assert api.strlen(uc, 0x100) == 6
    assert api.strcpy(uc, 0x200, 0x100) == 0x200
    assert uc.mem_read(0x200, 7) == b'benign\0'
    assert api.strcmp(uc, 0x100, 0x200) == 0
    uc.mem_write(0x300, b'example\0')
    assert api.strcmp(uc, 0x100, 0x300) == 0xffffffff
    assert api.strcmp(uc, 0x300, 0x100) == 1
    assert api.strncpy(uc, 0x400, 0x100, 10) == 0x400
    assert uc.mem_read(0x400, 10) == b'benign'+bytes(4)
    assert api.strncpy(uc, 0x400, 0x300, 3) == 0x400
    assert uc.mem_read(0x400, 3) == b'exa'  # No terminator when truncated.


def test_guest_memory_operations_handle_overlap_zero_size_and_unsigned_fill():
    model, uc, _ = fixture_model()
    api = model.crt_buffers
    uc.mem_write(0x100, b'abcdefgh')
    assert api.copy(uc, 0x200, 0x100, 8) == 0x200
    assert api.memcmp(uc, 0x100, 0x200, 8) == 0
    assert api.copy(uc, 0x102, 0x100, 6, True) == 0x102
    assert uc.mem_read(0x100, 8) == b'ababcdef'
    with pytest.raises(UnsupportedAPI, match='Overlapping'):
        api.copy(uc, 0x101, 0x100, 4)
    assert api.memset(uc, 0x200, 0x123, 4) == 0x200
    assert uc.mem_read(0x200, 4) == b'####'
    assert api.copy(uc, 0, 0, 0) == 0 and api.memcmp(uc, 0, 0, 0) == 0
    assert api.strncpy(uc, 0, 0, 0) == 0


def test_guest_strings_stop_at_mapped_page_end_and_enforce_explicit_budget():
    model, uc, _ = fixture_model()
    uc.mem_write(0xffc, b'end\0')
    read = uc.mem_read
    def bounded(address, count):
        assert address+count <= 0x1000
        return read(address, count)
    uc.mem_read = bounded
    assert model.crt_buffers.strlen(uc, 0xffc) == 3
    uc.mem_read = read
    uc.mem_write(0x1000, b'x'*model.limit)
    with pytest.raises(UnsupportedAPI, match='Unterminated'):
        model.crt_buffers.strlen(uc, 0x1000)
    with pytest.raises(UnsupportedAPI, match='budget'):
        model.crt_buffers.memset(uc, 0x100, 0, model.limit+1)


@pytest.mark.parametrize('left,right', [(b'path/', b'file'), (b'', b'file'), (b'path', b''), (b'', b''), (b'\xff', b'\x80')])
def test_lstrcat_ansi_appends_bytes_and_keeps_terminator(left, right):
    model, uc, _ = fixture_model()
    uc.mem_write(0x100, left+b'\0'+b'?'*32)
    uc.mem_write(0x200, right+b'\0')
    model.last_error=123
    assert model.crt_buffers.lstrcat_a(uc, 0x100, 0x200)==0x100
    assert uc.mem_read(0x100, len(left)+len(right)+2)==left+right+b'\0?'
    assert uc.mem_read(0x200, len(right)+1)==right+b'\0' and model.last_error==123


@pytest.mark.parametrize('destination,source', [(0,0x200),(0x100,0),(0,0)])
def test_lstrcat_null_pointer_returns_failure_without_guest_memory_access(destination, source):
    model, uc, _=fixture_model()
    uc.mem_read=lambda *_:pytest.fail('NULL input must not be dereferenced')
    assert model.crt_buffers.lstrcat_a(uc,destination,source)==0


@pytest.mark.parametrize('operation', ['read','write'])
def test_lstrcat_guest_access_fault_returns_null_without_swallowing_other_errors(operation):
    from unicorn import UcError,UC_ERR_READ_UNMAPPED,UC_ERR_WRITE_UNMAPPED
    model,uc,_=fixture_model();uc.mem_write(0x100,b'left\0');uc.mem_write(0x200,b'right\0')
    def fault(*_):raise UcError(UC_ERR_READ_UNMAPPED if operation=='read' else UC_ERR_WRITE_UNMAPPED)
    setattr(uc,'mem_'+operation,fault)
    assert model.crt_buffers.lstrcat_a(uc,0x100,0x200)==0
    def bug(*_):raise RuntimeError('model defect')
    setattr(uc,'mem_'+operation,bug)
    with pytest.raises(RuntimeError,match='model defect'):model.crt_buffers.lstrcat_a(uc,0x100,0x200)


def test_lstrcat_overlap_and_aggregate_budget_fail_before_any_write():
    model,uc,_=fixture_model();uc.mem_write(0x100,b'benign\0');uc.mem_write(0x200,b'fixture\0')
    with pytest.raises(UnsupportedAPI,match='Overlapping'):model.crt_buffers.lstrcat_a(uc,0x100,0x102)
    assert uc.mem_read(0x100,7)==b'benign\0'
    model.limit=10
    with pytest.raises(UnsupportedAPI,match='budget'):model.crt_buffers.lstrcat_a(uc,0x100,0x200)
    assert uc.mem_read(0x100,7)==b'benign\0'


def test_lstrcat_dispatch_uses_stdcall_and_preserves_return_address():
    import struct
    model,uc,_=fixture_model();model.install({})
    uc.mem_write(0x100,b'left\0');uc.mem_write(0x200,b'right\0')
    uc.mem_write(0x300,struct.pack('<III',0x401234,0x100,0x200))
    value,esp=model.handler.apicall(0,'lstrcatA',uc,0x300,False)
    assert (value,esp)==(0x100,0x308)
    assert uc.mem_read(esp,4)==struct.pack('<I',0x401234)
    assert uc.mem_read(0x100,10)==b'leftright\0'
